mapper.select:
SELECT h.ID AS id, h.INSTANCE_ID AS instanceId, h.NODE_ID AS nodeId, h.INPUT_DATA AS inputData, h.OUTPUT_DATA AS outputData, h.EXECUTION_MS AS executionMs, h.ENV_CODE AS envCode, h.DELETED AS deleted, h.CREATE_USER AS createUser, h.CREATE_TIME AS createTime, h.UPDATE_USER AS updateUser, h.UPDATE_TIME AS updateTime FROM AST_FLOW_NODE_HISTORY h WHERE (h.DELETED = 0 OR h.DELETED IS NULL)
AND h.INSTANCE_ID = #{req.instanceId}
AND h.NODE_ID LIKE CONCAT('%', #{req.nodeId}, '%')
AND h.ENV_CODE = #{req.envCode}
ORDER BY h.UPDATE_TIME DESC, h.ID DESC
